<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { useI18n } from 'vue-i18n'
import { getTool } from '../registry'
import { useToolProcessing } from '../useToolProcessing'
import { attackCatalogMetadata, groupByTactic, recognise, searchTechniques, toCsv, toMarkdown, type AttackTechnique } from './mitre'
const { t } = useI18n(); const tool = getTool('soc-tools.mitre'); const input = ref(''); const parsed = ref(''); const query = ref(''); const selected = ref<AttackTechnique[]>([]); const unknown = ref<string[]>([]); const grouped = ref(false); const status = ref(''); const output = ref('')
function process() { const result = recognise(parsed.value); selected.value = [...result.matched]; unknown.value = [...result.unknown] }; const { inputBytes, isOverLimit, schedule } = useToolProcessing({ input: parsed, output, maxInputBytes: tool.recommendedMaxInputBytes, process }); watch(input, (value) => { parsed.value = value; schedule() }, { immediate: true })
const results = computed(() => searchTechniques(query.value).slice(0, 30)); const groups = computed(() => groupByTactic(selected.value)); function add(item: AttackTechnique) { if (!selected.value.some((x) => x.id === item.id)) selected.value = [...selected.value, item] }; function remove(id: string) { selected.value = selected.value.filter((x) => x.id !== id) }; function label(tactic: string) { const key = `tools.evidencetimeline.tactics.${tactic}`; return t(key) !== key ? t(key) : tactic.replaceAll('-', ' ') }; async function copy(text: string) { try { await navigator.clipboard.writeText(text); status.value = t('tools.mitre.copied') } catch { status.value = t('tools.mitre.copyFailed') } }; function download(text: string, extension: string) { const url = URL.createObjectURL(new Blob([text], { type: 'text/plain' })); const a = document.createElement('a'); a.href = url; a.download = `mitre-mapping.${extension}`; a.click(); URL.revokeObjectURL(url) }
</script>
<template><section class="shell" :aria-label="t('tools.mitre.name')"><header><span>{{ t('tools.mitre.name') }}</span><span>ATT&amp;CK {{ attackCatalogMetadata.version }}</span></header><p class="muted">{{ t('tools.mitre.disclaimer') }}</p><section class="panel"><label>{{ t('tools.mitre.inputLabel') }}<textarea v-model="input" rows="7" spellcheck="false" :placeholder="t('tools.mitre.inputPlaceholder')" :aria-invalid="isOverLimit" /></label><p class="muted">{{ inputBytes }} B · {{ t('tools.mitre.catalogDate', { date: attackCatalogMetadata.date }) }}</p><p v-if="isOverLimit" class="error">{{ t('tools.mitre.overLimit') }}</p></section><section class="panel"><label>{{ t('tools.mitre.searchLabel') }}<input v-model="query" type="search" :placeholder="t('tools.mitre.searchPlaceholder')" /></label><div v-if="query" class="results"><button v-for="item in results" :key="item.id" type="button" @click="add(item)"><span class="mono">{{ item.id }}</span> {{ item.name }} <span class="muted">{{ item.tactics.join(', ') }}</span></button><p v-if="!results.length" class="muted">{{ t('tools.mitre.noMatches') }}</p></div></section><section class="panel"><div class="heading"><h2>{{ t('tools.mitre.mapping') }}</h2><label class="toggle"><input v-model="grouped" type="checkbox">{{ t('tools.mitre.groupByTactic') }}</label></div><p v-if="unknown.length" class="unknown mono">{{ t('tools.mitre.unknown', { ids: unknown.join(', ') }) }}</p><template v-if="grouped"><div v-for="group in groups" :key="group.tactic"><h3>{{ label(group.tactic) }}</h3><div v-for="item in group.techniques" :key="`${group.tactic}-${item.id}`" class="row"><span class="mono id">{{ item.id }}</span><span>{{ item.name }}</span><span class="tags"><span v-for="tactic in item.tactics" :key="tactic" class="tag">{{ label(tactic) }}</span></span><button type="button" @click="remove(item.id)">{{ t('tools.mitre.remove') }}</button><span class="url mono">{{ item.url }}</span></div></div></template><template v-else><div v-for="item in selected" :key="item.id" class="row"><span class="mono id">{{ item.id }}</span><span>{{ item.name }}</span><span class="tags"><span v-for="tactic in item.tactics" :key="tactic" class="tag">{{ label(tactic) }}</span></span><button type="button" @click="remove(item.id)">{{ t('tools.mitre.remove') }}</button><span class="url mono">{{ item.url }}</span></div></template><p v-if="!selected.length" class="muted">{{ t('tools.mitre.empty') }}</p></section><section class="panel"><h2>{{ t('tools.mitre.export') }}</h2><button type="button" @click="copy(toCsv(selected))">{{ t('tools.mitre.copyCsv') }}</button> <button type="button" @click="download(toCsv(selected), 'csv')">{{ t('tools.mitre.downloadCsv') }}</button> <button type="button" @click="copy(toMarkdown(selected))">{{ t('tools.mitre.copyMarkdown') }}</button> <button type="button" @click="download(toMarkdown(selected), 'md')">{{ t('tools.mitre.downloadMarkdown') }}</button><p class="muted" aria-live="polite">{{ status }}</p></section></section></template>
<style scoped>.shell{margin-top:24px;border:1px solid var(--border-hairline);border-radius:8px;background:var(--surface-raised);color:var(--text-primary);overflow:hidden}.shell>header,.panel{padding:16px 24px}.shell>header{display:flex;justify-content:space-between;background:var(--surface-overlay);color:var(--text-secondary);font:.9rem var(--font-mono)}.shell>.muted{padding:0 24px}.panel{border-top:1px solid var(--border-hairline)}h2{margin:0 0 10px;font-size:1.1rem}h3{margin:16px 0 8px}label{display:flex;flex-direction:column;gap:6px}textarea,input{box-sizing:border-box;width:100%;min-height:44px;border:1px solid var(--border-strong);border-radius:5px;background:var(--surface-overlay);color:var(--text-primary);font:inherit;padding:9px 10px}textarea{resize:vertical}.muted{color:var(--text-muted)}.mono{font-family:var(--font-mono)}.heading{display:flex;justify-content:space-between}.toggle{flex-direction:row;align-items:center}.toggle input{width:18px}.results{margin-top:10px;border:1px solid var(--border-hairline)}.results button{display:block;width:100%;min-height:44px;padding:9px;border:0;border-bottom:1px solid var(--border-hairline);background:var(--surface-overlay);color:var(--text-primary);text-align:left;font:inherit;cursor:pointer}.row{display:grid;grid-template-columns:8rem minmax(10rem,1fr) minmax(10rem,auto) auto;gap:10px;align-items:center;border-top:1px solid var(--border-hairline);padding:10px 0}.row .url{grid-column:1/-1;color:var(--text-muted);overflow-wrap:anywhere}.id{color:var(--accent-strong)}.tags{display:flex;flex-wrap:wrap;gap:5px}.tag{padding:4px 7px;border:1px solid var(--border-strong);border-radius:999px;background:var(--surface-overlay);color:var(--text-muted)}button{min-height:44px;padding:8px 12px;border:1px solid var(--border-strong);border-radius:5px;background:var(--surface-overlay);color:var(--text-primary);font:inherit;cursor:pointer}button:focus-visible,input:focus-visible,textarea:focus-visible{outline:2px solid var(--accent);outline-offset:2px}.unknown{padding:10px;border:1px solid var(--border-strong);overflow-wrap:anywhere}@media(max-width:760px){.shell>header,.panel{padding-inline:16px}.shell>.muted{padding-inline:16px}.heading{display:block}.row{grid-template-columns:1fr}.row .url{grid-column:auto}}
</style>
